#!/usr/bin/env sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Generated by build.py from recipe.yml for recipe dns-resolve-names-over-tls. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p site/.surl/dns site
cat > site/.surl/dns/example.test.zone <<'EOF'
$ORIGIN example.test.
$TTL 300
@   IN SOA ns1.example.test. hostmaster.example.test. 1 3600 600 86400 300
@   IN NS  ns1.example.test.
api IN A   127.0.0.1
EOF
printf '%s\n' 'orders api: up' > site/status.txt
cat > call-by-name.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Usage: sh call-by-name.sh DNS-PORT NAME HTTP-PORT PATH. Looks NAME up over DNS over TLS on
# 127.0.0.1:DNS-PORT, trusting server.pem, then fetches http://NAME:HTTP-PORT/PATH from the
# address the answer gave. A failed lookup exits with curl's code; no A record exits 6.
answer=$(curl -sS --max-time 10 --dns-transport tls --cacert server.pem "dns://127.0.0.1:$1/$2") || exit
addr=$(printf '%s\n' "$answer" | awk -F '\t' 'NF == 5 && $4 == "A" { print $5; exit }')
if [ -z "$addr" ]; then echo "$2 did not resolve" >&2; exit 6; fi
echo "$2 is $addr"
curl -sS --max-time 10 --resolve "$2:$3:$addr" "http://$2:$3$4"
EOF
openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"
surl --directory site --cert server.pem --key server.key --dns-transport tls dns://127.0.0.1:8080/ http://127.0.0.1:8081/ &
sleep 1
sh call-by-name.sh 8080 api.example.test 8081 /status.txt
kill $(jobs -p)
